import{_ as e,o,c as r,a0 as i}from"./chunks/framework.DQOulFGV.js";const h=JSON.parse('{"title":"Quick Start","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/start.md","filePath":"en/guide/start.md"}'),a={name:"en/guide/start.md"};function n(s,t,l,c,u,d){return o(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><p>Welcome to <strong>KernelEX</strong>! This guide will walk you through the system requirements, permission setup, and how to execute your very first script.</p><hr><h2 id="📱-system-requirements" tabindex="-1">📱 System Requirements <a class="header-anchor" href="#📱-system-requirements" aria-label="Permalink to &quot;📱 System Requirements&quot;">​</a></h2><p>Before getting started, please ensure your Android device meets the following requirements:</p><ul><li><strong>Operating System</strong>: Android 8.0 (API 26) or higher</li><li><strong>CPU Architecture</strong>: <code>arm64-v8a</code>, <code>armeabi-v7a</code>, <code>x86_64</code></li><li><strong>ROOT Solution</strong>: <strong>Magisk</strong>, <strong>KernelSU</strong>, or <strong>APatch</strong> installed and active</li><li><strong>Storage Permission</strong>: All-files access permission required on Android 11+ to manage external scripts</li></ul><hr><h2 id="🔑-permission-setup" tabindex="-1">🔑 Permission Setup <a class="header-anchor" href="#🔑-permission-setup" aria-label="Permalink to &quot;🔑 Permission Setup&quot;">​</a></h2><p>When launching KernelEX for the first time, you will be greeted by the <strong>Permission Gate</strong>:</p><ol><li><strong>ROOT Superuser Permission</strong>: Tap &quot;Request ROOT Access&quot; and grant permanent superuser privileges in your manager (Magisk / KernelSU / APatch).</li><li><strong>All-Files Access</strong>: Navigate to system settings to enable all-files management so KernelEX can load scripts from external storage.</li><li><strong>Ignore Battery Optimization (Recommended)</strong>: Request exclusion from battery optimization to prevent background script terminations.</li></ol><div class="tip custom-block"><p class="custom-block-title">Automatic Transition</p><p>Once all required permissions are granted, KernelEX will automatically transition to the main interface.</p></div><hr><h2 id="🚀-executing-your-first-script" tabindex="-1">🚀 Executing Your First Script <a class="header-anchor" href="#🚀-executing-your-first-script" aria-label="Permalink to &quot;🚀 Executing Your First Script&quot;">​</a></h2><p>KernelEX offers three flexible execution workflows:</p><h3 id="method-1-home-path-input-picker" tabindex="-1">Method 1: Home Path Input / Picker <a class="header-anchor" href="#method-1-home-path-input-picker" aria-label="Permalink to &quot;Method 1: Home Path Input / Picker&quot;">​</a></h3><ol><li>Go to the <strong>Home</strong> tab at the bottom;</li><li>Type in an absolute path or tap <strong>&quot;Pick from File Manager&quot;</strong> to select a <code>.sh</code> or <code>.so</code> file;</li><li>Tap <strong>&quot;Execute Now&quot;</strong>, and KernelEX will switch to the <strong>Terminal</strong> tab with live log streaming.</li></ol><h3 id="method-2-workspace-directory-launch" tabindex="-1">Method 2: Workspace Directory Launch <a class="header-anchor" href="#method-2-workspace-directory-launch" aria-label="Permalink to &quot;Method 2: Workspace Directory Launch&quot;">​</a></h3><ol><li>Place scripts or binaries directly into <code>/data/adb/KernelEX/</code>;</li><li>On the <strong>Home</strong> tab, click on any file in the workspace list to select and run it.</li></ol><h3 id="method-3-file-manager-context-action" tabindex="-1">Method 3: File Manager Context Action <a class="header-anchor" href="#method-3-file-manager-context-action" aria-label="Permalink to &quot;Method 3: File Manager Context Action&quot;">​</a></h3><ol><li>Go to the <strong>Files</strong> tab;</li><li>Navigate to your script, long-press the file item to open the action menu;</li><li>Select <strong>&quot;Add to KernelEX&quot;</strong> (if &quot;Auto Execute&quot; is enabled in Settings, it starts immediately).</li></ol><hr><h2 id="💻-terminal-controls-interaction" tabindex="-1">💻 Terminal Controls &amp; Interaction <a class="header-anchor" href="#💻-terminal-controls-interaction" aria-label="Permalink to &quot;💻 Terminal Controls &amp; Interaction&quot;">​</a></h2><p>In the <strong>Terminal</strong> tab, you can:</p><ul><li><strong>Send Standard Input (stdin)</strong>: Type parameters or responses in the bottom input bar and tap Send or Enter.</li><li><strong>Send Interrupt (Ctrl+C)</strong>: Tap <strong>&quot;Interrupt&quot;</strong> to dispatch a <code>SIGINT</code> (<code>kill -2</code>) signal to the active process.</li><li><strong>Force Kill</strong>: Tap <strong>&quot;Kill Process&quot;</strong> to terminate stuck tasks (<code>kill -9</code>).</li><li><strong>Copy Logs</strong>: Tap <strong>&quot;Copy Output&quot;</strong> to copy plain-text console logs to your clipboard.</li><li><strong>Clear &amp; Rerun</strong>: Tap <strong>&quot;Clear&quot;</strong> to reset the console or <strong>&quot;Rerun&quot;</strong> to restart the last task.</li></ul>',24)])])}const p=e(a,[["render",n]]);export{h as __pageData,p as default};
